{"edits": [{"finding_ids": ["app/api_errors.py:10:validator"], "search": "# Map Pydantic's error messages to our stable public error codes.
MESSAGE_CODES = {
    "field required": "MISSING",
    "value is not a valid integer": "NOT_AN_INTEGER",
    "ensure this value has at least": "TOO_SHORT",
}", "replace": "# Map Pydantic's error types to our stable public error codes.
MESSAGE_CODES = {
    "missing": "MISSING",
    "int_parsing": "NOT_AN_INTEGER",
    "int_type": "NOT_AN_INTEGER",
    "string_too_short": "TOO_SHORT",
}", "explanation": "Pydantic v2 reworded error messages (e.g. 'Field required'), so message-prefix matching no longer works. Map the stable v2 error 'type' identifiers instead."}, {"finding_ids": ["app/api_errors.py:10:validator"], "search": "            code = next((c for m, c in MESSAGE_CODES.items() if err["msg"].startswith(m)), "INVALID")", "replace": "            code = MESSAGE_CODES.get(err["type"], "INVALID")", "explanation": "Look up the code by v2 error type rather than by v1 message text."}], "notes": "The validator migration to @field_validator + @classmethod was already correct and is kept. The failure came from v2 changing error message text; I switched to matching err['type'], which is stable across v2 versions."}
